#include "config_store_host.h"
#include "config_store.h"
#include <pthread.h>
#include <setjmp.h>
#include <string.h>
#include "driver/gpio.h"
#include "esp_system.h"
#include "esp_timer.h"
#include "freertos/task.h"
#include "nvs_flash.h"

#define HOST_MAX_ENTRIES 192U
#define HOST_MAX_HANDLES 4U
#define CONFIG_NS_NAME "libre_desk"
#define SETUP_NS_NAME "libre_setup"
#define HOST_NAMESPACE_COUNT 2U

typedef struct { bool present; char key[TASK7_HOST_MAX_KEY]; nvs_type_t type; uint32_t number; char string[TASK7_HOST_MAX_STRING]; } host_entry_t;
typedef struct { bool open; bool pending_namespace; size_t ns_index; char ns[TASK7_HOST_MAX_KEY]; nvs_open_mode_t mode; host_entry_t view[HOST_MAX_ENTRIES]; } host_handle_t;
static host_entry_t durable[HOST_NAMESPACE_COUNT][HOST_MAX_ENTRIES];
static bool namespace_exists[HOST_NAMESPACE_COUNT];
static host_handle_t handles[HOST_MAX_HANDLES];
static pthread_mutex_t state_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t state_changed = PTHREAD_COND_INITIALIZER;
static task7_host_trace_event_t trace[TASK7_HOST_MAX_TRACE];
static size_t trace_count, operation_count, fail_at;
static esp_err_t fail_error, fail_next_error;
static bool fail_after;
static esp_err_t init_first = ESP_OK, init_recovery = ESP_OK, flash_erase_result = ESP_OK;
static size_t init_count, global_erase_count, namespace_erase_count;
static esp_err_t gpio_config_result = ESP_OK; static bool task_create_fail;
static TaskFunction_t task_code; static void *task_argument; static UBaseType_t task_priority; static uint32_t task_stack_depth;
static uint64_t gpio_mask; static int gpio_mode, gpio_pull_up, gpio_pull_down, gpio_interrupt;
static const int *gpio_levels; static const int64_t *gpio_times; static size_t gpio_count, gpio_index, restart_count, delay_count;
static __thread size_t critical_depth;
static pthread_mutex_t critical_lock = PTHREAD_MUTEX_INITIALIZER;
static jmp_buf task_escape; static bool task_escape_active;
static pthread_mutex_t *transaction_mutex; static StaticSemaphore_t *transaction_buffer; static bool mutex_create_fail, mutex_take_fail, mutex_take_fail_once, mutex_give_fail;
static bool transaction_mutex_initialized;
static pthread_t transaction_owner;
static __thread size_t transaction_owner_depth;
static size_t mutex_contention, max_transaction_owners, transaction_owners;
static size_t pause_at; static bool paused, pause_release;

static void text_copy(char *d,size_t n,const char *s){size_t i=0;if(n==0)return;while(i+1<n&&s&&s[i]){d[i]=s[i];i++;}d[i]=0;}
static void clear_entry(host_entry_t *e){memset(e,0,sizeof(*e));}
static host_entry_t *find(host_entry_t *a,const char *key){size_t i;for(i=0;i<HOST_MAX_ENTRIES;i++)if(a[i].present&&strcmp(a[i].key,key)==0)return &a[i];return NULL;}
static host_entry_t *find_or_create(host_entry_t *a,const char *key){size_t i;host_entry_t *e=find(a,key);if(e)return e;for(i=0;i<HOST_MAX_ENTRIES;i++)if(!a[i].present){clear_entry(&a[i]);a[i].present=true;text_copy(a[i].key,sizeof(a[i].key),key);return &a[i];}return NULL;}
static void trace_event(task7_host_trace_kind_t kind,const char *key,nvs_type_t type,uint32_t value,nvs_handle_t h,nvs_open_mode_t mode){task7_host_trace_event_t *e;const char *ns=CONFIG_NS_NAME;if(trace_count>=TASK7_HOST_MAX_TRACE)return;if(kind==TASK7_TRACE_OPEN&&key)ns=key;else if(h>0&&h<=HOST_MAX_HANDLES&&handles[h-1].open)ns=handles[h-1].ns;e=&trace[trace_count++];memset(e,0,sizeof(*e));e->kind=kind;e->type=type;e->value=value;e->handle=h;e->mode=mode;e->mutex_depth=transaction_owner_depth;e->critical_depth=critical_depth;text_copy(e->namespace_name,sizeof(e->namespace_name),ns);if(key&&kind!=TASK7_TRACE_OPEN)text_copy(e->key,sizeof(e->key),key);}
static esp_err_t fault(task7_host_trace_kind_t k,const char *key,nvs_type_t t,uint32_t v,nvs_handle_t h,nvs_open_mode_t m){esp_err_t e=ESP_OK;pthread_mutex_lock(&state_lock);trace_event(k,key,t,v,h,m);operation_count++;if(pause_at&&operation_count==pause_at){paused=true;pthread_cond_broadcast(&state_changed);while(!pause_release)pthread_cond_wait(&state_changed,&state_lock);paused=false;pause_at=0;pause_release=false;}if(fail_next_error!=ESP_OK){e=fail_next_error;fail_next_error=ESP_OK;}else if(fail_at&&operation_count==fail_at){if(fail_after)e=ESP_OK;else{e=fail_error;fail_at=0;}}pthread_mutex_unlock(&state_lock);return e;}
static bool after_fault(void){if(fail_at&&operation_count==fail_at&&fail_after){fail_at=0;return true;}if(fail_at&&operation_count==fail_at&&!fail_after){fail_at=0;}return false;}
static esp_err_t apply_after_fault(esp_err_t result){return after_fault()?fail_error:result;}
static host_handle_t *get_handle(nvs_handle_t h){return h>0&&h<=HOST_MAX_HANDLES&&handles[h-1].open?&handles[h-1]:NULL;}
static void seed_entry(const char *key,nvs_type_t t,uint32_t n,const char*s){host_entry_t*e=find_or_create(durable[0],key);if(!e)return;e->type=t;e->number=n;e->string[0]=0;if(t==NVS_TYPE_STR)text_copy(e->string,sizeof(e->string),s);namespace_exists[0]=true;}

void task7_host_reset_uninitialized(void){extern void config_store_test_reset(void);extern void provisioning_test_reset(void);pthread_mutex_lock(&state_lock);if(transaction_mutex_initialized){(void)pthread_mutex_destroy(transaction_mutex);transaction_mutex_initialized=false;}config_store_test_reset();provisioning_test_reset();memset(durable,0,sizeof(durable));memset(handles,0,sizeof(handles));memset(namespace_exists,0,sizeof(namespace_exists));trace_count=operation_count=fail_at=0;fail_error=fail_next_error=ESP_OK;fail_after=false;pause_at=0;paused=false;pause_release=false;init_first=init_recovery=ESP_OK;init_count=global_erase_count=namespace_erase_count=0;flash_erase_result=ESP_OK;gpio_config_result=ESP_OK;task_create_fail=false;task_code=NULL;task_argument=NULL;task_priority=0;task_stack_depth=0;gpio_mask=0;gpio_mode=gpio_pull_up=gpio_pull_down=gpio_interrupt=0;gpio_levels=NULL;gpio_times=NULL;gpio_count=gpio_index=restart_count=delay_count=0;critical_depth=0;mutex_create_fail=mutex_take_fail=mutex_take_fail_once=mutex_give_fail=false;mutex_contention=max_transaction_owners=transaction_owners=0;transaction_mutex=NULL;transaction_buffer=NULL;transaction_owner_depth=0;pthread_mutex_unlock(&state_lock);}
void task7_host_reset(void){task7_host_reset_uninitialized();(void)config_store_init();task7_host_clear_trace();}
void task7_host_power_cycle(void){pthread_mutex_lock(&state_lock);memset(handles,0,sizeof(handles));trace_count=operation_count=fail_at=0;fail_error=fail_next_error=ESP_OK;fail_after=false;pthread_mutex_unlock(&state_lock);}
void task7_host_pause_after_operation(size_t n){pthread_mutex_lock(&state_lock);pause_at=n;paused=false;pause_release=false;pthread_mutex_unlock(&state_lock);}
bool task7_host_wait_until_paused(void){bool result;pthread_mutex_lock(&state_lock);while(!paused)pthread_cond_wait(&state_changed,&state_lock);result=paused;pthread_mutex_unlock(&state_lock);return result;}
void task7_host_release_pause(void){pthread_mutex_lock(&state_lock);pause_release=true;pthread_cond_broadcast(&state_changed);pthread_mutex_unlock(&state_lock);}
void task7_host_clear_trace(void){pthread_mutex_lock(&state_lock);trace_count=operation_count=fail_at=0;fail_error=fail_next_error=ESP_OK;fail_after=false;pthread_mutex_unlock(&state_lock);}
size_t task7_host_trace_count(void){size_t n;pthread_mutex_lock(&state_lock);n=trace_count;pthread_mutex_unlock(&state_lock);return n;} const task7_host_trace_event_t *task7_host_trace_at(size_t i){return i<trace_count?&trace[i]:NULL;} size_t task7_host_operation_count(void){size_t n;pthread_mutex_lock(&state_lock);n=operation_count;pthread_mutex_unlock(&state_lock);return n;}
void task7_host_fail_at(size_t n,esp_err_t e){pthread_mutex_lock(&state_lock);fail_at=n;fail_error=e;fail_after=false;fail_next_error=ESP_OK;pthread_mutex_unlock(&state_lock);} void task7_host_fail_at_after(size_t n,esp_err_t e){pthread_mutex_lock(&state_lock);fail_at=n;fail_error=e;fail_after=true;fail_next_error=ESP_OK;pthread_mutex_unlock(&state_lock);} void task7_host_clear_failure(void){pthread_mutex_lock(&state_lock);fail_at=0;fail_error=fail_next_error=ESP_OK;fail_after=false;pthread_mutex_unlock(&state_lock);} void task7_host_fail_next(esp_err_t e){pthread_mutex_lock(&state_lock);fail_next_error=e;fail_at=0;fail_after=false;pthread_mutex_unlock(&state_lock);}
void task7_host_seed_setup_u8(const char*k,uint8_t v){host_entry_t*e;pthread_mutex_lock(&state_lock);e=find_or_create(durable[1],k);if(e){e->type=NVS_TYPE_U8;e->number=v;e->string[0]=0;namespace_exists[1]=true;}pthread_mutex_unlock(&state_lock);} void task7_host_seed_setup_u16(const char*k,uint16_t v){host_entry_t*e;pthread_mutex_lock(&state_lock);e=find_or_create(durable[1],k);if(e){e->type=NVS_TYPE_U16;e->number=v;e->string[0]=0;namespace_exists[1]=true;}pthread_mutex_unlock(&state_lock);} bool task7_host_read_setup_u8(const char*k,uint8_t*v){host_entry_t*e;bool ok=false;pthread_mutex_lock(&state_lock);e=find(durable[1],k);if(e&&e->type==NVS_TYPE_U8&&v){*v=(uint8_t)e->number;ok=true;}pthread_mutex_unlock(&state_lock);return ok;}
void task7_host_seed_u8(const char*k,uint8_t v){pthread_mutex_lock(&state_lock);seed_entry(k,NVS_TYPE_U8,v,NULL);pthread_mutex_unlock(&state_lock);} void task7_host_seed_u16(const char*k,uint16_t v){pthread_mutex_lock(&state_lock);seed_entry(k,NVS_TYPE_U16,v,NULL);pthread_mutex_unlock(&state_lock);} void task7_host_seed_u32(const char*k,uint32_t v){pthread_mutex_lock(&state_lock);seed_entry(k,NVS_TYPE_U32,v,NULL);pthread_mutex_unlock(&state_lock);} void task7_host_seed_str(const char*k,const char*v){pthread_mutex_lock(&state_lock);seed_entry(k,NVS_TYPE_STR,0,v);pthread_mutex_unlock(&state_lock);} void task7_host_remove(const char*k){pthread_mutex_lock(&state_lock);host_entry_t*e=find(durable[0],k);if(e)clear_entry(e);pthread_mutex_unlock(&state_lock);}
static bool read_number(const char*k,nvs_type_t t,uint32_t*v){host_entry_t*e=find(durable[0],k);if(!e||e->type!=t)return false;*v=e->number;return true;}
bool task7_host_read_u8(const char*k,uint8_t*v){uint32_t n;if(!read_number(k,NVS_TYPE_U8,&n))return false;*v=(uint8_t)n;return true;} bool task7_host_read_u16(const char*k,uint16_t*v){uint32_t n;if(!read_number(k,NVS_TYPE_U16,&n))return false;*v=(uint16_t)n;return true;} bool task7_host_read_u32(const char*k,uint32_t*v){return read_number(k,NVS_TYPE_U32,v);} bool task7_host_read_str(const char*k,char*v,size_t n){host_entry_t*e=find(durable[0],k);if(!e||e->type!=NVS_TYPE_STR||strlen(e->string)+1>n)return false;strcpy(v,e->string);return true;}
void task7_host_seed_wrong_type_u16(const char*k,uint16_t v){task7_host_seed_u16(k,v);} void task7_host_seed_wrong_type_u32(const char*k,uint32_t v){task7_host_seed_u32(k,v);} void task7_host_seed_oversized_str(const char*k,size_t n){host_entry_t*e=find_or_create(durable[0],k);size_t i;if(!e)return;e->present=true;e->type=NVS_TYPE_STR;for(i=0;i<n&&i+1<sizeof(e->string);i++)e->string[i]='x';e->string[i]=0;namespace_exists[0]=true;}
void task7_host_set_init_results(esp_err_t a,esp_err_t b){pthread_mutex_lock(&state_lock);init_first=a;init_recovery=b;init_count=0;pthread_mutex_unlock(&state_lock);} void task7_host_set_flash_erase_result(esp_err_t e){pthread_mutex_lock(&state_lock);flash_erase_result=e;pthread_mutex_unlock(&state_lock);} size_t task7_host_global_erase_count(void){size_t n;pthread_mutex_lock(&state_lock);n=global_erase_count;pthread_mutex_unlock(&state_lock);return n;} size_t task7_host_namespace_erase_count(void){size_t n;pthread_mutex_lock(&state_lock);n=namespace_erase_count;pthread_mutex_unlock(&state_lock);return n;}
void task7_host_set_gpio_config_result(esp_err_t e){gpio_config_result=e;} void task7_host_set_task_create_fail(bool b){task_create_fail=b;} void task7_host_set_gpio_samples(const int*l,const int64_t*t,size_t n){gpio_levels=l;gpio_times=t;gpio_count=n;gpio_index=0;}
int task7_host_run_created_task(void){int e;if(!task_code)return -1;task_escape_active=true;e=setjmp(task_escape);if(e==0)task_code(task_argument);task_escape_active=false;return e;} size_t task7_host_restart_count(void){return restart_count;} size_t task7_host_delay_count(void){return delay_count;} size_t task7_host_critical_depth(void){return critical_depth;} BaseType_t task7_host_created_task_priority(void){return (BaseType_t)task_priority;} uint32_t task7_host_created_task_stack_depth(void){return task_stack_depth;} uint64_t task7_host_gpio_mask(void){return gpio_mask;} int task7_host_gpio_mode(void){return gpio_mode;} int task7_host_gpio_pull_up(void){return gpio_pull_up;} int task7_host_gpio_pull_down(void){return gpio_pull_down;} int task7_host_gpio_interrupt(void){return gpio_interrupt;}
void task7_host_set_mutex_failures(bool c,bool t,bool g){pthread_mutex_lock(&state_lock);mutex_create_fail=c;mutex_take_fail=t;mutex_give_fail=g;pthread_mutex_unlock(&state_lock);} void task7_host_set_mutex_take_fail_once(void){pthread_mutex_lock(&state_lock);mutex_take_fail_once=true;pthread_mutex_unlock(&state_lock);} size_t task7_host_mutex_contention(void){size_t n;pthread_mutex_lock(&state_lock);n=mutex_contention;pthread_mutex_unlock(&state_lock);return n;} size_t task7_host_max_transaction_owners(void){size_t n;pthread_mutex_lock(&state_lock);n=max_transaction_owners;pthread_mutex_unlock(&state_lock);return n;}

esp_err_t nvs_open(const char*ns,nvs_open_mode_t mode,nvs_handle_t*out){size_t i,ns_index;esp_err_t e=fault(TASK7_TRACE_OPEN,ns,NVS_TYPE_ANY,0,0,mode);if(e!=ESP_OK)return e;/* Deterministic fake choice: an AFTER-open failure is consumed before allocation, so failed opens never publish a handle or namespace. */if(after_fault())return fail_error;if(!out||!ns)return ESP_ERR_INVALID_ARG;if(strcmp(ns,CONFIG_NS_NAME)==0)ns_index=0U;else if(strcmp(ns,SETUP_NS_NAME)==0)ns_index=1U;else return ESP_ERR_INVALID_ARG;if(!namespace_exists[ns_index]&&mode==NVS_READONLY)return ESP_ERR_NVS_NOT_FOUND;for(i=0;i<HOST_MAX_HANDLES;i++)if(!handles[i].open){handles[i].open=true;handles[i].pending_namespace=false;handles[i].ns_index=ns_index;handles[i].mode=mode;text_copy(handles[i].ns,sizeof(handles[i].ns),ns);memcpy(handles[i].view,durable[ns_index],sizeof(handles[i].view));*out=(nvs_handle_t)(i+1);return ESP_OK;}return ESP_ERR_NO_MEM;}
static void consume_namespace_erase(host_handle_t*x){if(x->pending_namespace){namespace_erase_count++;x->pending_namespace=false;}}
void nvs_close(nvs_handle_t h){host_handle_t*x=get_handle(h);trace_event(TASK7_TRACE_CLOSE,NULL,NVS_TYPE_ANY,0,h,x?x->mode:NVS_READONLY);if(x)memset(x,0,sizeof(*x));}
static esp_err_t set_value(host_handle_t*x,nvs_handle_t h,const char*k,nvs_type_t t,uint32_t n,const char*s,task7_host_trace_kind_t kind){host_entry_t*e;esp_err_t r=fault(kind,k,t,n,h,x?x->mode:NVS_READONLY);if(r!=ESP_OK)return r;if(!x||x->mode!=NVS_READWRITE)return apply_after_fault(ESP_ERR_NVS_READ_ONLY);e=find_or_create(x->view,k);if(!e)return apply_after_fault(ESP_FAIL);e->type=t;e->number=n;e->string[0]=0;if(t==NVS_TYPE_STR){if(strlen(s)+1>TASK7_HOST_MAX_STRING)return apply_after_fault(ESP_ERR_NVS_VALUE_TOO_LONG);text_copy(e->string,sizeof(e->string),s);}if(after_fault()){memcpy(durable[x->ns_index],x->view,sizeof(x->view));namespace_exists[x->ns_index]=true;consume_namespace_erase(x);return fail_error;}return ESP_OK;}
esp_err_t nvs_set_u8(nvs_handle_t h,const char*k,uint8_t v){return set_value(get_handle(h),h,k,NVS_TYPE_U8,v,NULL,TASK7_TRACE_SET_U8);} esp_err_t nvs_set_u16(nvs_handle_t h,const char*k,uint16_t v){return set_value(get_handle(h),h,k,NVS_TYPE_U16,v,NULL,TASK7_TRACE_SET_U16);} esp_err_t nvs_set_u32(nvs_handle_t h,const char*k,uint32_t v){return set_value(get_handle(h),h,k,NVS_TYPE_U32,v,NULL,TASK7_TRACE_SET_U32);} esp_err_t nvs_set_str(nvs_handle_t h,const char*k,const char*v){if(!v)return ESP_ERR_INVALID_ARG;return set_value(get_handle(h),h,k,NVS_TYPE_STR,0,v,TASK7_TRACE_SET_STR);}
static esp_err_t get_value(host_handle_t*x,nvs_handle_t h,const char*k,nvs_type_t t,uint32_t*v,bool *copied,task7_host_trace_kind_t kind){host_entry_t*e;*copied=false;esp_err_t r=fault(kind,k,t,0,h,x?x->mode:NVS_READONLY);if(r!=ESP_OK)return r;if(!x||!v)return apply_after_fault(ESP_ERR_INVALID_ARG);e=find(x->view,k);if(!e)return apply_after_fault(ESP_ERR_NVS_NOT_FOUND);if(e->type!=t)return apply_after_fault(ESP_ERR_NVS_TYPE_MISMATCH);*v=e->number;*copied=true;return apply_after_fault(ESP_OK);}
esp_err_t nvs_get_u8(nvs_handle_t h,const char*k,uint8_t*v){uint32_t n=0;bool copied;esp_err_t e=get_value(get_handle(h),h,k,NVS_TYPE_U8,&n,&copied,TASK7_TRACE_GET_U8);if(copied)*v=(uint8_t)n;return e;} esp_err_t nvs_get_u16(nvs_handle_t h,const char*k,uint16_t*v){uint32_t n=0;bool copied;esp_err_t e=get_value(get_handle(h),h,k,NVS_TYPE_U16,&n,&copied,TASK7_TRACE_GET_U16);if(copied)*v=(uint16_t)n;return e;} esp_err_t nvs_get_u32(nvs_handle_t h,const char*k,uint32_t*v){bool copied;return get_value(get_handle(h),h,k,NVS_TYPE_U32,v,&copied,TASK7_TRACE_GET_U32);}
esp_err_t nvs_get_str(nvs_handle_t h,const char*k,char*v,size_t*l){host_handle_t*x=get_handle(h);host_entry_t*e;size_t req;task7_host_trace_kind_t kind=v?TASK7_TRACE_GET_STR:TASK7_TRACE_GET_STR_QUERY;esp_err_t r=fault(kind,k,NVS_TYPE_STR,0,h,x?x->mode:NVS_READONLY);if(r!=ESP_OK)return r;if(!x||!l)return apply_after_fault(ESP_ERR_INVALID_ARG);e=find(x->view,k);if(!e)return apply_after_fault(ESP_ERR_NVS_NOT_FOUND);if(e->type!=NVS_TYPE_STR)return apply_after_fault(ESP_ERR_NVS_TYPE_MISMATCH);req=strlen(e->string)+1;if(!v){*l=req;return apply_after_fault(ESP_OK);}if(*l<req)return apply_after_fault(ESP_ERR_NVS_INVALID_LENGTH);memcpy(v,e->string,req);*l=req;return apply_after_fault(ESP_OK);}
esp_err_t nvs_erase_key(nvs_handle_t h,const char*k){host_handle_t*x=get_handle(h);host_entry_t*e;esp_err_t r=fault(TASK7_TRACE_ERASE_KEY,k,NVS_TYPE_ANY,0,h,x?x->mode:NVS_READONLY);if(r!=ESP_OK)return r;if(!x||x->mode!=NVS_READWRITE)return apply_after_fault(ESP_ERR_NVS_READ_ONLY);e=find(x->view,k);if(!e){if(after_fault()){memcpy(durable[x->ns_index],x->view,sizeof(x->view));namespace_exists[x->ns_index]=true;consume_namespace_erase(x);return fail_error;}return ESP_ERR_NVS_NOT_FOUND;}clear_entry(e);if(after_fault()){memcpy(durable[x->ns_index],x->view,sizeof(x->view));namespace_exists[x->ns_index]=true;consume_namespace_erase(x);return fail_error;}return ESP_OK;}
esp_err_t nvs_erase_all(nvs_handle_t h){host_handle_t*x=get_handle(h);esp_err_t r=fault(TASK7_TRACE_ERASE_ALL,NULL,NVS_TYPE_ANY,0,h,x?x->mode:NVS_READONLY);if(r!=ESP_OK)return r;if(!x||x->mode!=NVS_READWRITE)return apply_after_fault(ESP_ERR_NVS_READ_ONLY);memset(x->view,0,sizeof(x->view));x->pending_namespace=true;if(after_fault()){memcpy(durable[x->ns_index],x->view,sizeof(x->view));namespace_exists[x->ns_index]=true;consume_namespace_erase(x);return fail_error;}return ESP_OK;}
esp_err_t nvs_commit(nvs_handle_t h){host_handle_t*x=get_handle(h);esp_err_t r=fault(TASK7_TRACE_COMMIT,NULL,NVS_TYPE_ANY,0,h,x?x->mode:NVS_READONLY);if(r!=ESP_OK)return r;if(!x||x->mode!=NVS_READWRITE)return apply_after_fault(ESP_ERR_NVS_READ_ONLY);memcpy(durable[x->ns_index],x->view,sizeof(x->view));namespace_exists[x->ns_index]=true;consume_namespace_erase(x);if(after_fault())return fail_error;return ESP_OK;}
esp_err_t nvs_flash_init(void){esp_err_t r=fault(TASK7_TRACE_FLASH_INIT,NULL,NVS_TYPE_ANY,0,0,NVS_READWRITE);if(r!=ESP_OK)return r;return init_count++==0?init_first:init_recovery;} esp_err_t nvs_flash_erase(void){esp_err_t r=fault(TASK7_TRACE_FLASH_ERASE,NULL,NVS_TYPE_ANY,0,0,NVS_READWRITE);global_erase_count++;if(r!=ESP_OK)return r;if(flash_erase_result==ESP_OK){memset(durable,0,sizeof(durable));memset(namespace_exists,0,sizeof(namespace_exists));}return flash_erase_result;}

esp_err_t gpio_config(const gpio_config_t*c){esp_err_t r=fault(TASK7_TRACE_GPIO_CONFIG,NULL,NVS_TYPE_ANY,0,0,NVS_READWRITE);if(r!=ESP_OK)return r;if(!c)return ESP_ERR_INVALID_ARG;gpio_mask=c->pin_bit_mask;gpio_mode=c->mode;gpio_pull_up=c->pull_up_en;gpio_pull_down=c->pull_down_en;gpio_interrupt=c->intr_type;return gpio_config_result;} int gpio_get_level(gpio_num_t g){(void)g;if(gpio_index>=gpio_count){if(task_escape_active)longjmp(task_escape,2);return -1;}return gpio_levels[gpio_index];} int64_t esp_timer_get_time(void){int64_t r;if(gpio_index>=gpio_count){if(task_escape_active)longjmp(task_escape,2);return -1;}r=gpio_times[gpio_index++];return r;}
TaskHandle_t xTaskCreateStatic(TaskFunction_t f,const char*n,uint32_t sd,void*a,UBaseType_t p,StackType_t*sb,StaticTask_t*tb){esp_err_t r=fault(TASK7_TRACE_TASK_CREATE,n,NVS_TYPE_ANY,sd,0,NVS_READWRITE);(void)sb;(void)tb;if(r!=ESP_OK||task_create_fail)return NULL;task_code=f;task_argument=a;task_priority=p;task_stack_depth=sd;return (TaskHandle_t)(uintptr_t)1;} void vTaskDelay(TickType_t t){trace_event(TASK7_TRACE_DELAY,NULL,NVS_TYPE_ANY,t,0,NVS_READWRITE);delay_count++;} void esp_restart(void){trace_event(TASK7_TRACE_RESTART,NULL,NVS_TYPE_ANY,0,0,NVS_READWRITE);restart_count++;if(task_escape_active)longjmp(task_escape,1);}
void task7_enter_critical(portMUX_TYPE*m){(void)m;pthread_mutex_lock(&critical_lock);critical_depth++;trace_event(TASK7_TRACE_CRITICAL_ENTER,NULL,NVS_TYPE_ANY,0,0,NVS_READWRITE);} void task7_exit_critical(portMUX_TYPE*m){(void)m;trace_event(TASK7_TRACE_CRITICAL_EXIT,NULL,NVS_TYPE_ANY,0,0,NVS_READWRITE);if(critical_depth)critical_depth--;pthread_mutex_unlock(&critical_lock);}
SemaphoreHandle_t xSemaphoreCreateMutexStatic(StaticSemaphore_t*b){if(mutex_create_fail)return NULL;transaction_buffer=b;transaction_mutex=(pthread_mutex_t*)b;if(pthread_mutex_init(transaction_mutex,NULL)!=0)return NULL;transaction_mutex_initialized=true;return (SemaphoreHandle_t)b;} BaseType_t xSemaphoreTake(SemaphoreHandle_t s,TickType_t t){int rc;bool once;(void)t;if(!s||s!=(SemaphoreHandle_t)transaction_buffer)return pdFALSE;pthread_mutex_lock(&state_lock);once=mutex_take_fail_once;mutex_take_fail_once=false;pthread_mutex_unlock(&state_lock);if(mutex_take_fail||once)return pdFALSE;rc=pthread_mutex_trylock(transaction_mutex);if(rc!=0){pthread_mutex_lock(&state_lock);mutex_contention++;pthread_mutex_unlock(&state_lock);if(pthread_mutex_lock(transaction_mutex)!=0)return pdFALSE;}transaction_owner=pthread_self();transaction_owner_depth++;pthread_mutex_lock(&state_lock);transaction_owners++;if(transaction_owners>max_transaction_owners)max_transaction_owners=transaction_owners;pthread_mutex_unlock(&state_lock);return pdTRUE;} BaseType_t xSemaphoreGive(SemaphoreHandle_t s){bool fail;if(!s||s!=(SemaphoreHandle_t)transaction_buffer||transaction_owner_depth==0U||!pthread_equal(transaction_owner,pthread_self()))return pdFALSE;pthread_mutex_lock(&state_lock);if(transaction_owners>0U)transaction_owners--;fail=mutex_give_fail;mutex_give_fail=false;pthread_mutex_unlock(&state_lock);transaction_owner_depth--;if(pthread_mutex_unlock(transaction_mutex)!=0)return pdFALSE;return fail?pdFALSE:pdTRUE;}
